UPDATE courses SET description='Learn how domain names lead to DNS answers. Follow a lookup, build common records, predict cached results and recognise lookup failures through hands-on practice. Six beginner lessons, about 55 minutes, and no videos. All lessons are free. Enroll free with a verified account to save lesson completion.'
WHERE id='dns-fundamentals' AND slug='dns-fundamentals' AND description='Learn how domain names lead to DNS answers. Follow a lookup, build common records, predict cached results and recognise lookup failures through hands-on practice. Six beginner lessons, about 55 minutes, and no videos. All lessons are free previews; saving completion requires an account with course access.';
UPDATE lessons SET content=REPLACE(content,'Build each record below using the name and value in its prompt. Choose a type, supply its owner and value, then check all six. Edit any mistaken field and check again.','Build one record at a time using the name and value in its prompt. Choose a type, supply its owner and value, then select Check answer. Read the explanation and select Next task. Use Previous task to revisit an answer or Reset records to start over.') WHERE id='dns-record-practice' AND section_id IN (SELECT id FROM sections WHERE course_id='dns-fundamentals');
UPDATE lessons SET content=REPLACE(content,'1. Read the job on each card.
2. Enter the owner name: the name receiving the record.
3. Choose a record type and copy the supplied value.
4. For MX, also enter the mail preference.
5. Select Check records after completing all six cards.

Read the feedback beside each card. Edit a mistaken field, then check again. Reset records clears all six cards.','Build one record at a time using the name and value in its prompt. Choose a type, supply its owner and value, then select Check answer. Read the explanation and select Next task. Use Previous task to revisit an answer or Reset records to start over.') WHERE id='dns-record-practice' AND section_id IN (SELECT id FROM sections WHERE course_id='dns-fundamentals');
UPDATE lessons SET content=REPLACE(content,'Choose one best answer for every question. Select Check answers to read the explanations, including those for correct choices. Review the matching lesson for anything you missed, then use Reset quiz to retry.','Answer one question at a time. Select Check answer to read the explanation, then Next question to continue. A wrong answer includes a Review lesson link; leaving this quiz resets your answers. Use Previous question to revisit an answer or Reset quiz to start over.') WHERE id='dns-self-check' AND section_id IN (SELECT id FROM sections WHERE course_id='dns-fundamentals');
